import {popeyeLamps} from './popeye-playfield.mjs';
import {t2Lamps} from './t2-playfield.mjs';
const escape=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function createLampMatrix({root,onSelect=()=>{},onOpen=()=>{}}){
 root.innerHTML=`<div class="lamp-matrix-heading"><div><h2 id="lampMatrixTitle">Lamp matrix</h2><p>Controlled lamps · select a circuit to inspect its bulb.</p></div><span id="lampMatrixCount" role="status"></span></div><div class="lamp-matrix-scroll" tabindex="0" role="region" aria-label="Lamp matrix; scroll horizontally for all columns"><table class="lamp-matrix-table"><caption>Columns 1–8, rows 1–8. Lamp number = column × 10 + row.</caption><thead><tr><th scope="col">Row</th>${Array.from({length:8},(_,i)=>`<th scope="col">${i+1}</th>`).join('')}</tr></thead><tbody id="lampMatrixRows"></tbody></table></div><div class="lamp-matrix-selection"><p id="lampMatrixSelected">Select a lamp to inspect it.</p><button id="lampMatrixOpen" type="button" disabled>Open in Lighting</button></div><p class="lamp-matrix-note">Filled lights show live ROM output; outlined cells show your selection. Colors follow your LED plan. Selecting a cell does not activate a lamp. GI strings and flashers are available in Lighting.</p>`;
 const $=id=>root.querySelector('#'+id);let game='',lamps=[],cells=[],live=null,selected=null,colors={},signature='';
 function paint(){const active=new Set(live?.lamps||[]),used=lamps.filter(l=>!l.unused),on=used.filter(l=>active.has(l.number)).length;
  $('lampMatrixCount').textContent=live?on+' / '+used.length+' on':'Waiting for game';
  for(const cell of cells){const n=Number(cell.dataset.lampMatrix),lamp=lamps.find(l=>l.number===n),isOn=!lamp?.unused&&active.has(n);cell.classList.toggle('lamp-output-on',!!isOn);cell.classList.toggle('lamp-output-selected',n===selected);cell.setAttribute('aria-pressed',String(n===selected));cell.style.setProperty('--matrix-color',colors[n]||'#ffe1a3');cell.setAttribute('aria-label',n+': '+lamp.name+' · '+(lamp.unused?'unused':!live?'state unavailable':isOn?'on':'off'));cell.querySelector('.lamp-output-state').textContent=lamp.unused?'UNUSED':!live?'—':isOn?'ON':'OFF';}
  const lamp=lamps.find(l=>l.number===selected&&!l.unused);$('lampMatrixOpen').disabled=!lamp;$('lampMatrixSelected').textContent=lamp?lamp.number+' · '+lamp.name+' · '+(!live?'state unavailable':active.has(lamp.number)?'on':'off'):'Select a lamp to inspect it.';
 }
 root.addEventListener('click',event=>{const button=event.target.closest?.('[data-lamp-matrix]');if(button&&!button.disabled){event.preventDefault();onSelect(Number(button.dataset.lampMatrix));}});$('lampMatrixOpen').onclick=()=>{if(selected!==null)onOpen(selected);};
 return {updateGame(next){if(next===game)return;game=next;lamps=game==='t2_l8'?t2Lamps:popeyeLamps;live=null;selected=null;colors={};signature='';$('lampMatrixTitle').textContent=(game==='t2_l8'?'Terminator 2':'Popeye')+' lamp matrix';$('lampMatrixRows').innerHTML=Array.from({length:8},(_,r)=>`<tr><th scope="row">${r+1}</th>${Array.from({length:8},(_,c)=>{const n=(c+1)*10+r+1,l=lamps.find(l=>l.number===n);return `<td><button type="button" data-lamp-matrix="${n}" ${l.unused?'disabled':''} aria-pressed="false"><span class="lamp-output-number">${n}<i class="lamp-output-dot" aria-hidden="true"></i></span><span class="lamp-output-name">${escape(l.name)}</span><small class="lamp-output-state"></small></button></td>`;}).join('')}</tr>`).join('');cells=[...root.querySelectorAll('[data-lamp-matrix]')];paint();},updateLive(state){live=state;const next=JSON.stringify(state?.lamps??null);if(next!==signature){signature=next;paint();}},updatePlan(plan){selected=plan.selected?.kind==='insert'?plan.selected.number:null;colors=plan.colors||{};paint();}};
}
